import math
def inflate(grid, r):
    N, M = len(grid), len(grid[0])
    out = [list(row) for row in grid]
    for i in range(N):
        for j in range(M):
            if grid[i][j] == '#':
                for a in range(N):
                    for b in range(M):
                        if out[a][b] == '.' and math.hypot(a - i, b - j) <= r:
                            out[a][b] = '+'
    return ["".join(row) for row in out]

door = ["...#...", "...#...", ".......", ".......", ".......", "...#...", "...#..."]
for row in inflate(door, 1):
    print(row)

# 실행 결과
..+#+..
..+#+..
...+...
.......
...+...
..+#+..
..+#+..

class Bus:
    def __init__(self):
        self.subs = {}                    # 토픽 이름 -> 구독 함수 목록
    def subscribe(self, topic, cb):
        self.subs.setdefault(topic, []).append(cb)
    def publish(self, topic, msg):
        for cb in self.subs.get(topic, []):
            cb(msg)

bus = Bus()
bus.subscribe("/scan", lambda m: print("장애물 감지:", m))
bus.subscribe("/scan", lambda m: print("지도 작성:", m))
bus.publish("/scan", 1.2)
bus.publish("/odom", 3.0)

# 실행 결과
장애물 감지: 1.2
지도 작성: 1.2

