def navigate(dist, step, cancel_at=None):
    left, n = dist, 0
    while left > 0:
        n += 1
        left = round(max(left - step, 0), 2)
        print("피드백: 남은 거리", left)
        if n == cancel_at:
            return "CANCELED"
    return "SUCCEEDED"

print(navigate(1.0, 0.3, cancel_at=2))

